import{_ as a,o as e,c as n,a0 as s}from"./chunks/framework.D7EjqxMK.js";const g=JSON.parse('{"title":"ReAct 模式","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/03_高级模式/01_ReAct模式.md","filePath":"06-agent/03_高级模式/01_ReAct模式.md"}'),r={name:"06-agent/03_高级模式/01_ReAct模式.md"};function o(i,t,c,l,h,d){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="react-模式" tabindex="-1">ReAct 模式 <a class="header-anchor" href="#react-模式" aria-label="Permalink to &quot;ReAct 模式&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块三 · 03_高级模式 · 第 1 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：Agent 基础</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>**ReAct（Reasoning + Acting）**是 AI Agent 最经典的工作流模式，由 Yao et al. (2022) 在论文《ReAct: Synergizing Reasoning and Acting in Language Models》中首次提出。</p><p>核心思想：<strong>让 LLM 交替进行「推理」和「行动」</strong>。</p><hr><h2 id="_2-核心概念" tabindex="-1">2. 核心概念 <a class="header-anchor" href="#_2-核心概念" aria-label="Permalink to &quot;2. 核心概念&quot;">​</a></h2><p>ReAct 输出包含三个交替元素：</p><table tabindex="0"><thead><tr><th>元素</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><strong>Thought</strong></td><td>LLM 的推理过程</td><td>&quot;我需要先查天气&quot;</td></tr><tr><td><strong>Action</strong></td><td>调用的工具</td><td>&quot;search: 北京天气&quot;</td></tr><tr><td><strong>Observation</strong></td><td>工具返回的结果</td><td>&quot;北京: 25°C 晴&quot;</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought: 我需要查询北京的天气</span></span>
<span class="line"><span>Action: search(query=&quot;北京天气&quot;)</span></span>
<span class="line"><span>Observation: 北京: 25°C 晴</span></span>
<span class="line"><span>Thought: 天气信息已获取</span></span>
<span class="line"><span>Action: finish(answer=&quot;北京明天晴，25°C&quot;)</span></span></code></pre></div><h3 id="react-vs-传统-chain-of-thought" tabindex="-1">ReAct vs 传统 Chain of Thought <a class="header-anchor" href="#react-vs-传统-chain-of-thought" aria-label="Permalink to &quot;ReAct vs 传统 Chain of Thought&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统 CoT:   推理 → 推理 → 推理 → 回答（纯文字）</span></span>
<span class="line"><span>ReAct:      推理 → 行动 → 观察 → 推理 → 行动 → 回答（交替）</span></span></code></pre></div><hr><h2 id="_3-参考资料" tabindex="-1">3. 参考资料 <a class="header-anchor" href="#_3-参考资料" aria-label="Permalink to &quot;3. 参考资料&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noreferrer">ReAct: Synergizing Reasoning and Acting</a></li><li><a href="https://python.langchain.com/docs/modules/agents/agent_types/react/" target="_blank" rel="noreferrer">LangChain ReAct 文档</a></li><li><a href="https://jishuzhan.net/article/2053319676944515073" target="_blank" rel="noreferrer">ReAct 架构深度解析</a></li><li><a href="https://gitcode.csdn.net/69c1ee540a2f6a37c599e1e8.html" target="_blank" rel="noreferrer">ReAct、Plan-and-Execute、Reflection、Multi-Agent 工程范式</a></li></ul>`,16)])])}const u=a(r,[["render",o]]);export{g as __pageData,u as default};
